// --- Compatibility Enrichments for Redesigned Interview Preparation Workspace ---
function mapModuleToCategory(modNum: number): InterviewCategory {
  if (modNum === 1) return 'Substation Equipments';
  if ([2, 3, 4, 5, 6, 7, 8].includes(modNum)) return 'IEC 61850';
  if (modNum === 9) return 'SCADA';
  if (modNum === 10) return 'Protocols';
  if ([11, 12, 13].includes(modNum)) return 'Networking';
  if ([14, 15, 19].includes(modNum)) return 'Protection & Control';
  return 'Testing & Commissioning';
}

for (const q of INTERVIEW_QUESTIONS_BANK as any[]) {
  q.category = q.category || mapModuleToCategory(q.moduleNumber);
  q.questionTe = q.questionTe || (q.moduleTitleTe ? `${q.question} (${q.moduleTitleTe})` : q.question);
  q.shortAnswer = q.shortAnswer || q.shortAnswerEn || '';
  q.detailedAnswer =
    q.detailedAnswer ||
    (Array.isArray(q.detailedExplanationEn)
      ? q.detailedExplanationEn.join('\\n\\n')
      : String(q.detailedExplanationEn || ''));
  q.keyPointsToMention = q.keyPointsToMention || q.keyPointsToRememberEn || [];
  q.realSubstationExample = q.realSubstationExample || q.practicalExampleEn || '';
}

for (const sc of TROUBLESHOOTING_SCENARIOS_20 as any[]) {
  sc.number = sc.number ?? sc.scenarioNumber;
  sc.category = sc.category || String(sc.relatedSimulatorTab || 'Commissioning');
  sc.title = sc.title || sc.titleEn;
  sc.symptoms = sc.symptoms || sc.initialSymptomsEn || [];
  sc.rootCause = sc.rootCause || sc.confirmedRootCauseEn || '';
  sc.stepByStepFix = sc.stepByStepFix || [
    ...(sc.stepByStepDiagnosisEn || []),
    `Corrective Action: ${sc.correctiveActionEn || ''}`,
    `Verification: ${sc.verificationProcedureEn || ''}`,
  ];
}

export function evaluateMockAnswer(question: any, answerText: string) {
  const clean = (answerText || '').trim().toLowerCase();
  if (!clean) {
    return {
      score: 0,
      verdict: 'Needs Technical Detail',
      feedback: 'Please enter a technical explanation referencing relevant IEC 61850 Logical Nodes, protocols, or commissioning checks.',
    };
  }
  const keywords: string[] = question?.expectedKeywords || ['iec 61850', 'goose', 'mms', 'scada', 'ied'];
  const matched = keywords.filter((kw) => clean.includes(kw.toLowerCase()));
  const lengthBonus = Math.min(35, Math.round(clean.split(/\\s+/).length * 1.2));
  const kwScore = keywords.length > 0 ? Math.round((matched.length / keywords.length) * 65) : 50;
  const score = Math.min(100, Math.max(25, kwScore + lengthBonus));
  const verdict =
    score >= 85
      ? 'Senior Commissioning Ready'
      : score >= 65
      ? 'Strong Technical Pass'
      : 'Partial — Expand Key Standard Terms';
  const missing = keywords.filter((kw) => !clean.includes(kw.toLowerCase()));
  const feedback =
    missing.length === 0
      ? `Excellent engineering response! You covered all key terms (${matched.join(', ')}).`
      : `Good technical structure. Matched keywords: ${matched.length > 0 ? matched.join(', ') : 'general terms'}. Consider explicitly mentioning: ${missing.join(', ')}.`;
  return { score, verdict, feedback };
}
